//! SciPy.io-generated MAT-file (Level 5 / Version 7) interoperability suite.
//!
//! The 40 fixture files in `tests/data/` are generated by `scripts/validate_mat_v7.py`
//! (SciPy 1.18.1, `scipy.io.savemat`) and committed to the repository so the test
//! never depends on `target/` host state. Every file must load through
//! `rustlab_matio::load_mat` with the exact value class and shape that SciPy wrote.

use rustlab_math::Value;
use rustlab_matio::load_mat;
use std::path::PathBuf;

/// Expected MATLAB class name and 0-based shape for each fixture variable.
fn expected_class_and_shape(var_name: &str) -> (&'static str, Vec<usize>) {
    match var_name {
        "var_double_real" => ("double", vec![2, 3]),
        "var_double_complex" => ("double", vec![2, 2]),
        "var_single" => ("single", vec![2, 2]),
        "var_int8" => ("int8", vec![2, 2]),
        "var_uint8" => ("uint8", vec![2, 2]),
        "var_int16" => ("int16", vec![2, 2]),
        "var_uint16" => ("uint16", vec![2, 2]),
        "var_int32" => ("int32", vec![2, 2]),
        "var_uint32" => ("uint32", vec![2, 2]),
        "var_int64" => ("int64", vec![2, 2]),
        "var_uint64" => ("uint64", vec![2, 2]),
        "var_logical" => ("logical", vec![2, 2]),
        "var_char" => ("char", vec![1, 32]),
        "var_cell" => ("cell", vec![2, 2]),
        "var_struct" => ("struct", vec![1, 1]),
        "var_sparse" => ("double (sparse CSC)", vec![3, 3]),
        "var_tensor_3d" => ("double", vec![2, 3, 4]),
        "var_empty_0x0" => ("double", vec![0, 0]),
        "var_empty_0x5" => ("double", vec![0, 5]),
        _ => ("", Vec::new()), // unreachable for the committed fixture list
    }
}

/// MATLAB class name of a loaded value plus its 0-based shape (as `whos x` shows).
fn value_class_and_shape(v: &Value) -> (&'static str, Vec<usize>) {
    match v {
        Value::Double(d) => ("double", d.shape().to_vec()),
        Value::ComplexDouble(d) => ("double", d.shape().to_vec()),
        Value::Single(d) => ("single", d.shape().to_vec()),
        Value::Logical(d) => ("logical", d.shape().to_vec()),
        Value::Int8(d) => ("int8", d.shape().to_vec()),
        Value::Int16(d) => ("int16", d.shape().to_vec()),
        Value::Int32(d) => ("int32", d.shape().to_vec()),
        Value::Int64(d) => ("int64", d.shape().to_vec()),
        Value::UInt8(d) => ("uint8", d.shape().to_vec()),
        Value::UInt16(d) => ("uint16", d.shape().to_vec()),
        Value::UInt32(d) => ("uint32", d.shape().to_vec()),
        Value::UInt64(d) => ("uint64", d.shape().to_vec()),
        Value::Char(d) => ("char", d.shape().to_vec()),
        Value::String(d) => ("string", d.shape().to_vec()),
        Value::Cell(d) => ("cell", d.shape().to_vec()),
        Value::Struct(s) => ("struct", s.shape.clone()),
        Value::Sparse(c) => ("double (sparse CSC)", vec![c.rows(), c.cols()]),
        Value::FunctionHandle(_) => ("function_handle", Vec::new()),
    }
}

#[test]
fn test_scipy_generated_files_interop() {
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    let mat_dir = manifest_dir.join("tests").join("data");
    assert!(
        mat_dir.is_dir(),
        "fixture directory {:?} is missing; regenerate with `python scripts/validate_mat_v7.py`",
        mat_dir
    );

    let var_names = [
        "var_double_real",
        "var_double_complex",
        "var_single",
        "var_int8",
        "var_uint8",
        "var_int16",
        "var_uint16",
        "var_int32",
        "var_uint32",
        "var_int64",
        "var_uint64",
        "var_char",
        "var_logical",
        "var_cell",
        "var_struct",
        "var_sparse",
        "var_tensor_3d",
        "var_empty_0x0",
        "var_empty_0x5",
    ];

    let mut files = Vec::new();
    for name in var_names {
        files.push(format!("{name}_compressed.mat"));
        files.push(format!("{name}_uncompressed.mat"));
    }
    files.push("suite_all_types_compressed.mat".to_string());
    files.push("suite_all_types_uncompressed.mat".to_string());

    println!("\n=== SciPy MAT-File Interop Results (scipy.io.savemat -> rustlab-matio) ===");
    println!(
        "{:<40} {:>5}  {:<24} {:<24} result",
        "fixture file", "vars", "expected (class, shape)", "loaded (class, shape)"
    );

    let mut pass_count = 0usize;
    let mut fail_rows: Vec<String> = Vec::new();

    for file in &files {
        let path = mat_dir.join(file);
        assert!(
            path.is_file(),
            "committed fixture '{file}' is missing from tests/data"
        );

        let suite = file.starts_with("suite_");
        let file_var = if suite {
            None
        } else {
            let cut = file.rfind('_').unwrap_or(file.len());
            Some(&file[..cut])
        };

        let mut row_pass = false;
        let mut rows_detail = String::new();

        match load_mat(&path) {
            Ok(vars) => {
                if suite {
                    let missing: Vec<&str> = var_names
                        .iter()
                        .copied()
                        .filter(|n| !vars.contains_key(*n))
                        .collect();
                    row_pass = missing.is_empty();
                    if row_pass {
                        pass_count += 1;
                        rows_detail = format!("all {} vars present", var_names.len());
                    } else {
                        rows_detail = format!("missing vars: {missing:?}");
                    }
                    println!(
                        "{:<40} {:>5}  {:<24} {:<24} {}",
                        file,
                        vars.len(),
                        "-",
                        format!("{} vars", vars.len()),
                        if row_pass { "PASS" } else { "FAIL" }
                    );
                } else {
                    let name = file_var.unwrap_or_default();
                    match vars.get(name) {
                        Some(v) => {
                            let (got_class, got_shape) = value_class_and_shape(v);
                            let (want_class, want_shape) = expected_class_and_shape(name);
                            row_pass = want_class == got_class && want_shape == got_shape;
                            if row_pass {
                                pass_count += 1;
                            }
                            println!(
                                "{:<40} {:>5}  {:<24} {:<24} {}",
                                file,
                                vars.len(),
                                format!("{}, {:?}", want_class, want_shape),
                                format!("{}, {:?}", got_class, got_shape),
                                if row_pass { "PASS" } else { "FAIL" }
                            );
                            if !row_pass {
                                rows_detail = format!(
                                    "{file}: expected ({want_class}, {want_shape:?}), got ({got_class}, {got_shape:?})"
                                );
                            }
                        }
                        None => {
                            rows_detail = format!("{file}: variable `{name}` absent from file");
                            println!(
                                "{:<40} {:>5}  {:<24} {:<24} FAIL (absent)",
                                file,
                                vars.len(),
                                "-",
                                "-"
                            );
                        }
                    }
                }
            }
            Err(e) => {
                rows_detail = format!("{file}: load error {e:?}");
                println!(
                    "{:<40} {:>5}  {:<24} {:<24} LOAD ERROR",
                    file, "-", "-", "load error"
                );
            }
        }

        if !row_pass {
            fail_rows.push(rows_detail);
        }
    }

    println!(
        "\n[+] Interop summary: {pass_count}/{} fixture files passed",
        files.len()
    );

    assert!(
        fail_rows.is_empty(),
        "SciPy interop failures:\n{}",
        fail_rows.join("\n")
    );
    assert_eq!(pass_count, files.len(), "every fixture must pass");
}
